python3 -c "
import subprocess, re
# Use pdftotext to find page of References / Limitations
result = subprocess.run(['pdftotext', '-layout', 'main.pdf', '-'], capture_output=True, text=True)
text = result.stdout
pages = text.split('\x0c')
for i, page in enumerate(pages, 1):
    if 'Limitations' in page or 'References' in page or 'Appendix' in page:
        # Find which keyword
        keywords = []
        if 'Limitations' in page: keywords.append('Limitations')
        if 'References' in page: keywords.append('References')
        if re.search(r'Appendix|\\\\appendix', page): keywords.append('Appendix')
        print(f'Page {i}: {keywords}')
print(f'Total pages: {len(pages)-1}')
"
